//! Bit-precise integers on every back end. `tests/fixtures/programs/bit_int.c`
//! (generated by `scripts/generate_bit_int_program.py`) runs every operator,
//! conversion and folded constant of `_BitInt(N)` for widths 1 to 128; the
//! bundled Clang's build of it is the reference for both identities, and the
//! host GCC's (14 or later) must agree with it. `bit_int.wasm32.expected`
//! is what wasi-sdk's Clang build prints for `wasm32-wasip1`.
//! `bit_int_abi.c` links halves built by bcc's back ends, Clang and GCC in
//! every pairing, and `bit_int_objects.c` prints the bytes of `_BitInt`
//! objects, padding included.

#[cfg(test)]
#[expect(
    clippy::disallowed_types,
    clippy::disallowed_methods,
    clippy::disallowed_macros,
    reason = "Tests own process output and temporary files."
)]
mod tests {
    use std::{
        path::{
            Path,
            PathBuf,
        },
        process::{
            Command,
            Output,
        },
        sync::atomic::{
            AtomicU32,
            Ordering,
        },
    };

    use crate::native::run_native;

    const CLANG: &str = "target/llvm/bin/clang";

    /// Each operator at widths 1 to 128 over run-time and folded operands,
    /// conversions to and from every integer and real floating type, the
    /// usual arithmetic conversions, `wb` constants, bit-fields, `switch`
    /// and the overflow builtins print what Clang's and GCC's builds print,
    /// under each identity, interpreted before and after optimization and
    /// built through LLVM and the native back end.
    #[test]
    fn bit_int_programs_match_clang_and_gcc() {
        if !linux_x86_64() {
            return;
        }
        let source = fixture("bit_int.c");
        let expected = reference(CLANG, &source);
        if host_gcc_compiles(&source) {
            assert_eq!(reference("gcc", &source), expected, "GCC agrees with Clang");
        } else {
            eprintln!("note: no host GCC with _BitInt; the GCC identity uses Clang's output");
        }
        for identity in ["--compiler-identity=clang", "--compiler-identity=gcc"] {
            for flags in [
                &["--interpret", "--opt=none"][..],
                &["--interpret", "--opt=bcc"],
            ] {
                let output = bcc(&[&[identity, "-std=c23", &source][..], flags].concat());
                assert_eq!(
                    output.status.code(),
                    Some(0),
                    "{identity} {flags:?}: {}",
                    text(&output.stderr)
                );
                assert_lines(
                    &text(&output.stdout),
                    &expected,
                    &format!("{identity} {flags:?}"),
                );
            }
            for flags in [
                &["-O0"][..],
                &["-O2"],
                &["--backend=native"],
                &["--backend=native", "--opt=bcc"],
            ] {
                let executable = temporary("bit_int.exe");
                let built = bcc(&[
                    &[
                        identity,
                        "-std=c23",
                        &source,
                        "-o",
                        executable.to_str().unwrap(),
                    ][..],
                    flags,
                ]
                .concat());
                assert!(
                    built.status.success(),
                    "{identity} {flags:?}: {}",
                    text(&built.stderr)
                );
                let run = run_native(&mut Command::new(&executable)).unwrap();
                assert_eq!(run.status.code(), Some(0), "{identity} {flags:?}");
                assert_lines(
                    &text(&run.stdout),
                    &expected,
                    &format!("{identity} {flags:?}"),
                );
                std::fs::remove_file(executable).unwrap();
            }
        }
    }

    /// The same program built by bcc's WebAssembly back end for
    /// `wasm32-wasip1`, unoptimized and with both optimizers, prints what
    /// wasi-sdk's Clang build prints, under Node's WASI; without `node`
    /// on the path this is skipped.
    #[test]
    fn bit_int_programs_match_clang_on_wasm32() {
        if !Command::new("node")
            .arg("--version")
            .output()
            .is_ok_and(|output| output.status.success())
        {
            eprintln!("skipping wasm32: node is not on the path");
            return;
        }
        let source = fixture("bit_int.c");
        let expected = std::fs::read_to_string(fixture("bit_int.wasm32.expected")).unwrap();
        let runner = Path::new(env!("CARGO_MANIFEST_DIR")).join("scripts/wasm/run.mjs");
        for flags in [&["-O0"][..], &["-O2"], &["--opt=bcc"]] {
            let module = temporary("bit_int.wasm");
            let built = bcc(&[
                &[
                    "-std=c23",
                    "--target=wasm32-wasip1",
                    &source,
                    "-o",
                    module.to_str().unwrap(),
                ][..],
                flags,
            ]
            .concat());
            assert!(
                built.status.success(),
                "wasm32 {flags:?}: {}",
                text(&built.stderr)
            );
            let run = run_native(
                Command::new("node")
                    .arg("--no-warnings")
                    .arg(&runner)
                    .arg(&module),
            )
            .unwrap();
            assert_eq!(
                run.status.code(),
                Some(0),
                "wasm32 {flags:?}: {}",
                text(&run.stderr)
            );
            assert_lines(&text(&run.stdout), &expected, &format!("wasm32 {flags:?}"));
            std::fs::remove_file(module).unwrap();
        }
    }

    /// The bytes of static, automatic, member, array, compound-literal and
    /// (GCC's only) atomic `_BitInt` objects, padding bits included, are
    /// what each identity's compiler stores: the value extended from its
    /// width, in static initializers and at run time, before and after
    /// compound assignments. The WebAssembly layout is the same, so its
    /// build prints Clang's bytes.
    #[test]
    fn bit_int_object_bytes_match_each_compiler() {
        if !linux_x86_64() {
            return;
        }
        let source = fixture("bit_int_objects.c");
        let clang = reference(CLANG, &source);
        let mut references = vec![("--compiler-identity=clang", clang.clone())];
        if host_gcc_compiles(&source) {
            references.push(("--compiler-identity=gcc", reference("gcc", &source)));
        } else {
            eprintln!("note: no host GCC with _BitInt; skipping the GCC identity");
        }
        for (identity, expected) in &references {
            for flags in [
                &["--interpret", "--opt=none"][..],
                &["--interpret", "--opt=bcc"],
            ] {
                let output = bcc(&[&[*identity, "-std=c23", &source][..], flags].concat());
                assert_eq!(
                    output.status.code(),
                    Some(0),
                    "{identity} {flags:?}: {}",
                    text(&output.stderr)
                );
                assert_eq!(text(&output.stdout), *expected, "{identity} {flags:?}");
            }
            for flags in [
                &["-O0"][..],
                &["-O2"],
                &["--backend=native"],
                &["--backend=native", "--opt=bcc"],
            ] {
                let executable = temporary("objects.exe");
                let built = bcc(&[
                    &[
                        *identity,
                        "-std=c23",
                        &source,
                        "-o",
                        executable.to_str().unwrap(),
                    ][..],
                    flags,
                ]
                .concat());
                assert!(
                    built.status.success(),
                    "{identity} {flags:?}: {}",
                    text(&built.stderr)
                );
                let run = run_native(&mut Command::new(&executable)).unwrap();
                assert_eq!(run.status.code(), Some(0), "{identity} {flags:?}");
                assert_eq!(text(&run.stdout), *expected, "{identity} {flags:?}");
                std::fs::remove_file(executable).unwrap();
            }
        }
        if !Command::new("node")
            .arg("--version")
            .output()
            .is_ok_and(|output| output.status.success())
        {
            eprintln!("skipping wasm32: node is not on the path");
            return;
        }
        let runner = Path::new(env!("CARGO_MANIFEST_DIR")).join("scripts/wasm/run.mjs");
        for flags in [&["-O0"][..], &["-O2"], &["--opt=bcc"]] {
            let module = temporary("objects.wasm");
            let built = bcc(&[
                &[
                    "-std=c23",
                    "--target=wasm32-wasip1",
                    &source,
                    "-o",
                    module.to_str().unwrap(),
                ][..],
                flags,
            ]
            .concat());
            assert!(
                built.status.success(),
                "wasm32 {flags:?}: {}",
                text(&built.stderr)
            );
            let run = run_native(
                Command::new("node")
                    .arg("--no-warnings")
                    .arg(&runner)
                    .arg(&module),
            )
            .unwrap();
            assert_eq!(text(&run.stdout), clang, "wasm32 {flags:?}");
            std::fs::remove_file(module).unwrap();
        }
    }

    /// Arguments of every width class (narrower than `int`, in one general
    /// register, in two or on the stack 8-aligned after the registers run
    /// out), results, structure members and variadic arguments pass
    /// between halves built by bcc (LLVM at -O0 and -O2, and the native
    /// back end with and without its optimizer), Clang and GCC in both
    /// directions. Each side extends what it passes and ignores the padding
    /// bits of what it receives, which Clang leaves unextended in registers.
    #[test]
    fn bit_int_arguments_link_with_clang_and_gcc() {
        if !linux_x86_64() {
            return;
        }
        let source = fixture("bit_int_abi.c");
        let expected = reference(CLANG, &source);
        let gcc = host_gcc_compiles(&source);
        if gcc {
            assert_eq!(reference("gcc", &source), expected, "GCC agrees with Clang");
        }
        let bcc_binary = env!("CARGO_BIN_EXE_bcc-rust");
        let llvm = [bcc_binary, "-std=c23", "--backend=llvm"];
        let llvm_optimized = [bcc_binary, "-std=c23", "--backend=llvm", "-O2"];
        let native = [bcc_binary, "-std=c23", "--backend=native"];
        let native_optimized = [bcc_binary, "-std=c23", "--backend=native", "--opt=bcc"];
        let mut compilers: Vec<&[&str]> = vec![
            &[CLANG, "-std=c23", "-O1"],
            &llvm,
            &llvm_optimized,
            &native,
            &native_optimized,
        ];
        if gcc {
            compilers.push(&["gcc", "-std=c23", "-O1"]);
        }
        let half = |compiler: &[&str], which: &str| {
            let object = temporary(&format!("{which}.o"));
            let built = Command::new(compiler[0])
                .args(&compiler[1..])
                .args([&source, which, "-c", "-o", object.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                built.status.success(),
                "{compiler:?}: {}",
                text(&built.stderr)
            );
            object
        };
        for callee in &compilers {
            let definitions = half(callee, "-DCALLEE_ONLY");
            for caller in &compilers {
                let checks = half(caller, "-DCALLER_ONLY");
                let executable = temporary("abi.exe");
                let linked = Command::new(CLANG)
                    .args([&definitions, &checks])
                    .arg("-o")
                    .arg(&executable)
                    .output()
                    .unwrap();
                assert!(linked.status.success(), "{}", text(&linked.stderr));
                let run = run_native(&mut Command::new(&executable)).unwrap();
                assert_eq!(text(&run.stdout), expected, "{callee:?} {caller:?}");
                std::fs::remove_file(executable).unwrap();
                std::fs::remove_file(checks).unwrap();
            }
            std::fs::remove_file(definitions).unwrap();
        }
        for identity in ["--compiler-identity=clang", "--compiler-identity=gcc"] {
            let output = bcc(&[identity, "-std=c23", "--interpret", &source]);
            assert_eq!(text(&output.stdout), expected, "{identity}");
        }
    }

    /// Compares output with expectations line by line, reporting the first
    /// differences.
    fn assert_lines(output: &str, expected: &str, context: &str) {
        if output == expected {
            return;
        }
        let mismatches: Vec<String> = output
            .lines()
            .zip(expected.lines())
            .filter(|(line, want)| line != want)
            .take(20)
            .map(|(line, want)| format!("expected {want}\n     got {line}"))
            .collect();
        panic!(
            "{context}: {} lines against {} expected\n{}",
            output.lines().count(),
            expected.lines().count(),
            mismatches.join("\n")
        );
    }

    fn linux_x86_64() -> bool {
        cfg!(all(
            target_arch = "x86_64",
            target_os = "linux",
            target_env = "gnu"
        ))
    }

    fn fixture(name: &str) -> String {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/programs")
            .join(name)
            .to_str()
            .unwrap()
            .to_owned()
    }

    /// Whether the host GCC builds `source`: GCC 14 and later provide
    /// `_BitInt` on x86-64.
    fn host_gcc_compiles(source: &str) -> bool {
        let object = temporary("probe.o");
        let built = Command::new("gcc")
            .args(["-std=c23", source, "-c", "-o", object.to_str().unwrap()])
            .output()
            .is_ok_and(|output| output.status.success());
        if object.exists() {
            std::fs::remove_file(object).unwrap();
        }
        built
    }

    /// The output of `source` built by `compiler`; GCC calls libatomic for
    /// 16-byte atomic objects.
    fn reference(compiler: &str, source: &str) -> String {
        let executable = temporary("reference.exe");
        let built = Command::new(compiler)
            .args([source, "-std=c23", "-O0", "-w", "-o"])
            .arg(&executable)
            .args(if compiler == "gcc" {
                &["-latomic"][..]
            } else {
                &[]
            })
            .output()
            .unwrap();
        assert!(
            built.status.success(),
            "{compiler}: {}",
            text(&built.stderr)
        );
        let run = run_native(&mut Command::new(&executable)).unwrap();
        assert_eq!(run.status.code(), Some(0), "{compiler}");
        std::fs::remove_file(executable).unwrap();
        text(&run.stdout)
    }

    fn bcc(args: &[&str]) -> Output {
        run_native(
            Command::new(env!("CARGO_BIN_EXE_bcc-rust"))
                .args(args)
                .env("NO_COLOR", "1")
                .env_remove("CLICOLOR_FORCE"),
        )
        .unwrap()
    }

    /// Output bytes as text, with Windows line ends made plain.
    fn text(bytes: &[u8]) -> String {
        String::from_utf8_lossy(bytes).replace("\r\n", "\n")
    }

    /// A fresh path in the system temporary directory.
    fn temporary(name: &str) -> PathBuf {
        static NEXT: AtomicU32 = AtomicU32::new(0);
        std::env::temp_dir().join(format!(
            "bcc-bit-int-{}-{}-{name}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ))
    }
}
